public class StringTransformationDemo {
    public static void main(String[] args) {
        String rawInput = "   Hello-World-2024!   ";

        // 1. Whitespace stripping
        String stripped = rawInput.strip();
        System.out.println("Stripped: [" + stripped + "]");

        // 2. Case transformation
        String lower = stripped.toLowerCase();
        String upper = stripped.toUpperCase();
        System.out.println("Lower: " + lower);
        System.out.println("Upper: " + upper);

        // 3. Literal replacement
        String replacedHyphen = stripped.replace('-', ' ');
        System.out.println("Replaced char: " + replacedHyphen);

        String replacedWord = stripped.replace("World", "Universe");
        System.out.println("Replaced word: " + replacedWord);

        // 4. Regex replacement (replaceAll)
        // Replaces all digits with 'X'
        String masked = stripped.replaceAll("\\d", "X");
        System.out.println("Masked digits: " + masked);

        // 5. Method Chaining for pipeline sanitization
        String canonicalSlug = rawInput.strip().toLowerCase().replace(' ', '_').replace('!', '');
        System.out.println("Canonical Slug: " + canonicalSlug);
    }
}

