practiceProblems.solutionCode:
public class CardMasker {
    public static void main(String[] args) {
        String card = "4111-2222-3333-4444";
        String lastFour = card.substring(card.length() - 4);
        String masked = "****-****-****-" + lastFour;
        System.out.println("Masked Card: " + masked);
    }
}

